head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > isWFramePopup]<br/>현재 화면이 WFrame 유형의 팝업인지 여부를 반환합니다.",
    "validation" : [
        "현재 화면이 WFrame 유형의 팝업이면 true, 아니면 false 를 반환해야 합니다.",
        "WFrame 유형의 팝업은 '$p.openPopup()' 메소드 호출 시 options.type 속성값이 'wframePopup' 으로 설정된 팝업을 의미해야 합니다.",
        "options.type 이 'wframePopup' 이 아닌 팝업(예: 'iframePopup') 에서는 항상 false 를 반환해야 합니다.",
        "isClosest(선택) 파라미터가 true 이면 상위 프레임 체인을 최상위 프레임까지 순회하면서 WFrame 팝업 여부를 확인해야 합니다.",
        "isClosest(선택) 파라미터가 false 이면 현재 화면의 직접 부모 프레임만 확인해야 합니다.",
        "isClosest(선택) 생략 시 기본값 false 로 동작해야 합니다.",
        "WFrame Scope 가 아닌 최상위 페이지에서 호출하면 항상 false 값을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_openPopup_wframe_onclick = function () {
    var options = {
        id: "isWFramePopup_popup",
        type: "wframePopup",
        width: "700px",
        height: "400px",
        top: "100px",
        left: "100px",
        popupName: "isWFramePopup 테스트 팝업 (wframePopup)",
        modal: false
    };

    $p.openPopup("/sample/common_link/$p_isWFramePopup_1.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (type: 'wframePopup')");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 isWFramePopup() / isWFramePopup(true) 결과를 확인하세요.");
}



scwin.btn_openPopup_iframe_onclick = function () {
    var options = {
        id: "isWFramePopup_popup",
        type: "iframePopup",
        width: "700px",
        height: "400px",
        top: "100px",
        left: "100px",
        popupName: "isWFramePopup 테스트 팝업 (iframePopup)",
        modal: false
    };

    $p.openPopup("/sample/common_link/$p_isWFramePopup_1.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (type: 'iframePopup')");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 isWFramePopup() / isWFramePopup(true) 결과를 확인하세요.");
}
